use std::{fs,path::Path};use serde_json::{json,Value};use sha2::{Digest,Sha256};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-isolated-grouping");let src=r.join("candidate");let rel="crates/zopro-core/src/msm_affine/grouping.rs";let p=src.join(rel);let original=fs::read_to_string(&p).unwrap();fs::write(r.join("grouping.original.rs"),&original).unwrap();let selector=fs::read_to_string(r.join("selector.rs.txt")).unwrap();fs::write(&p,format!("{original}{selector}")).unwrap();
 let old_module=fs::read_to_string("/tmp/zopro-grouping-lower-bound/lower_bound.rs.txt").unwrap();let anchor="#[cfg(test)]\nmod tests {";assert_eq!(old_module.matches(anchor).count(),1);let extra="pub(super) fn eligible(n: usize) -> bool { words(n,80).is_some() }\n\n#[inline(never)]\npub(super) fn group_or_decline(scalars: &[[u64;4]]) -> Option<super::ScalarGroups> {\n    debug_assert!(eligible(scalars.len()));\n    let reservation=crate::msm_affine::grouping_cost::reserve(scalars.len(),80)?;\n    if declines(scalars,80) { return None; }\n    drop(reservation);\n    super::scalar_groups(scalars)\n}\n\n";
 let mut module=old_module.replacen(anchor,&format!("{extra}{anchor}"),1);module.push_str(&fs::read_to_string(r.join("routing-tests.rs.txt")).unwrap());let module_path=src.join("crates/zopro-core/src/msm_affine/grouping/lower_bound.rs");fs::create_dir_all(module_path.parent().unwrap()).unwrap();fs::write(module_path,module).unwrap();
 let rel2="crates/zopro-core/src/msm_affine.rs";let p=src.join(rel2);let old=fs::read_to_string(&p).unwrap();fs::write(r.join("msm_affine.original.rs"),&old).unwrap();let mut text=old.clone();let mut edits=Vec::new();for(before,after)in[("pub(super) use grouping::{group_witness, scalar_groups, ScalarGroups};","pub(super) use grouping::{group_witness, scalar_groups, ScalarGroups};\n#[cfg(zopro_isolated_grouping)]\nuse grouping::selected_scalar_groups;\n#[cfg(not(zopro_isolated_grouping))]\nuse grouping::scalar_groups as selected_scalar_groups;"),("if let Some(groups) = scalar_groups(canonical) {","if let Some(groups) = selected_scalar_groups(canonical) {"),(".then(|| scalar_groups(words))",".then(|| selected_scalar_groups(words))")]{assert_eq!(text.matches(before).count(),1,"{before}");text=text.replacen(before,after,1);edits.push(json!({"path":rel2,"before":before,"after":after}));}fs::write(p,text).unwrap();fs::write(r.join("edits.json"),serde_json::to_vec_pretty(&json!({"grouping_path":rel,"appended_selector":selector,"msm_affine_edits":edits,"original_grouping_prefix_unchanged":true})).unwrap()).unwrap();
 let ex=src.join("crates/zopro-bench/examples");fs::create_dir_all(ex.join("support")).unwrap();for rel in ["cpu-sdk.rs","support/perf.rs"]{fs::copy(Path::new("/home/ubuntu/src/zk-tools/zopro/crates/zopro-bench/examples").join(rel),ex.join(rel)).unwrap();}
 let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let mut pins=serde_json::Map::new();for(file,h)in m["source_files_sha256"].as_object().unwrap(){let p=src.join(file);if file==rel{assert_eq!(hash(r.join("grouping.original.rs")),h.as_str().unwrap());assert!(fs::read(&p).unwrap().starts_with(original.as_bytes()));}else if file==rel2{assert_eq!(hash(r.join("msm_affine.original.rs")),h.as_str().unwrap());}else{assert_eq!(hash(&p),h.as_str().unwrap());}pins.insert(p.display().to_string(),json!(hash(p)));}
 for file in ["crates/zopro-core/src/msm_affine/grouping/lower_bound.rs","crates/zopro-bench/examples/cpu-sdk.rs","crates/zopro-bench/examples/support/perf.rs"]{let p=src.join(file);pins.insert(p.display().to_string(),json!(hash(p)));}for file in ["prepare-build.rs","selector.rs.txt","routing-tests.rs.txt","design.md","audit.rs","audit/results.json","audit-tests.log"]{let p=r.join(file);pins.insert(p.display().to_string(),json!(hash(p)));}fs::write(r.join("source-pins.json"),serde_json::to_vec_pretty(&pins).unwrap()).unwrap();
 let rendered=fs::read_to_string("/tmp/zopro-grouping-lower-bound/native-plan.json").unwrap().replace("/tmp/zopro-grouping-lower-bound","/tmp/zopro-isolated-grouping").replace("zopro_grouping_lower_bound","zopro_isolated_grouping");let mut plan:Value=serde_json::from_str(&rendered).unwrap();for test in plan["steps"][2]["required_tests"].as_array_mut().unwrap(){assert!(test.as_str().unwrap().contains("lower_bound"));}plan["steps"][2]["required_tests"].as_array_mut().unwrap().extend([json!("msm_affine::grouping::lower_bound::routing_tests::complete_group_structure_matches_original"),json!("msm_affine::grouping::lower_bound::routing_tests::selector_only_admits_the_existing_small_interval")]);fs::write(r.join("native-plan.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();println!("170 originals recoverable;2existing/1new candidate files;{}pins",pins.len());}
